    input  wire              rst_n,
    input  wire [NL-1:0]     fck,
    input  wire [NL*LW-1:0]  l_i,
    output wire [NL*LW-1:0]  l_o,
    input  wire              x3_v,
    input  wire [511:0]      x3_d,
    input  wire [10:0]       x3_tag,
