    input  wire              ea_v,
    input  wire              ea_kind,
    input  wire [23:0]       ea_addr,
    output wire              ea_cr,
    output wire              eq_v,
    output wire [511:0]      eq_d,
    output wire              emb_ready,
    output wire              emb_fault,
    output wire [7:0]        emb_fault_code
