    // ---- receive side ------------------------------------------------------------------------------------------------
    wire [NL-1:0]      rv, rcr, rwf, rrf;
    wire [NL*523-1:0]  rd;                 // {tag 11, data 512}
    reg  [NL-1:0]      rtake;              // a word popped from a link's output FIFO (its credit back to the cdc_ch)
