    reg [OA:0]    lfw  [0:NL-1];
    reg [OA:0]    lfr  [0:NL-1];
    reg [NL-1:0]  lne;                      // link FIFO non-empty
    reg [NL-1:0]  lfo;                      // link FIFO overflow (sticky, per link)
