    end
    always @(posedge ck) if (!merge_fault && !flow_bad) begin
        if (xv_q) begin
            sd[sw[XA-1:0]] <= xd_q; st[sw[XA-1:0]] <= xt_q;
            sdst[sw[XA-1:0]] <= xd_q[511:510]; sbc[sw[XA-1:0]] <= 0;
        end
