            hd[hw[XA-1:0]] <= hd_q; ht[hw[XA-1:0]] <= ht_q;
            hdst[hw[XA-1:0]] <= stack_of(hd_q[24:0]); hbc[hw[XA-1:0]] <= ht_q[9:8] == K_BOOT_END;
