        if (!rn) begin
            sw<=0;sr<=0;hw<=0;hr<=0;xcr_q<=0;hcr_q<=0;ovf<=0;hovf<=0;lco<=0;lo_q<=0;
            for (i=0;i<NL;i=i+1) begin lc[i]<=CR[CW-1:0];lseen[i]<=0;end
